import { createSignal } from "solid-js";
const [count] = createSignal(1);
export const defined = {};
Object.defineProperty(defined, "v", { get: () => count(), enumerable: true });
export const valued = {};
Object.defineProperty(valued, "v", { value: 1 });
class Box { get v() { return count(); } }
export const box = new Box();
class Plain { w = 1; }
export const plain = new Plain();
export const proxied = new Proxy({}, { get: () => count() });
export const created = Object.create({ get v() { return count(); } });
export const dates = new Map();
